// Array parameter 'arr[]' decays immediately to pointer 'int*'
void operate_on_array(int arr[], size_t length) {
    // Array bounds [N] in parameter declaration are ignored (only 'int*' matters)
    // sizeof(arr) == sizeof(int*)

    // Modification simulates Call-by-Reference (modifies caller's array)
    arr[0] = 42; 
}

// Function signature is identical to the compiler:
void operate_on_array_ptr(int* ptr, size_t length) {
    // Access via pointer syntax
    *(ptr + 1) = 99; 
}

